js-easy2-double-later.alternative:
const doubleLater = promise => {
  const doubled = promise.then(value => {
    const result = value * 2;
    return result;
  });
  return doubled;
};

js-easy2-fallback-on-failure.alternative:
const withFallback = (promise, fallback) => {
  return promise.catch(error => {
    return fallback;
  });
};

js-easy2-total-when-ready.alternative:
const totalWhenReady = prices => {
  return Promise.all(prices).then(values => {
    let total = 0;
    for (const value of values) {
      total = total + value;
    }
    return total;
  });
};

js-easy2-fire-in-delay-order.wrong-late-capture:
const inDelayOrder = jobs => {
  return new Promise(resolve => {
    const fired = [];
    if (jobs.length === 0) {
      resolve(fired);
      return;
    }
    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      setTimeout(() => {
        fired.push(job.name);
        if (fired.length === jobs.length) {
          resolve(fired);
        }
      }, job.ms);
    }
  });
};

js-easy3-list-failures.alternative:
const failureMessages = promises => {
  return Promise.allSettled(promises).then(results => {
    const messages = [];
    for (const result of results) {
      if (result.status === "rejected") {
        messages.push(result.reason.message);
      }
    }
    return messages;
  });
};
